$entity=['id'=>'2','session_id'=>'1','kind'=>'npc','owner_uid'=>null];$session=['id'=>'1','owner_uid'=>'7'];$base=[['session_id'=>'1','entity_id'=>'2','controller_uid'=>'7','mode'=>'exclusive','assignment_version'=>'1','status'=>'active','valid_from'=>0,'valid_until'=>null,'permissions_json'=>'{"schema_version":1,"combat_operations_enabled":true}']];$roles=[['uid'=>'8','role'=>'player','expires_at'=>null],['uid'=>'9','role'=>'gm','expires_at'=>null],['uid'=>'7','role'=>'owner','expires_at'=>null]];
