$get=static fn(string $uid,array $effects,string $category='ordinary')=>AF_ACS_AuthorizationService::controller($entity,$base,$session,$roles,$uid,[],$category,['visible_entities'=>['2'=>'participants'],'control_effects'=>$effects,'encounter_id'=>'1']);
controlAssert($get('9',[$a,$b])!==null&&$get('8',[$a,$b])===null&&$get('7',[$a,$b])===null,'Priority/exclusive overlay');controlAssert($get('9',[$a,$b],'item_consume')===null&&$get('9',[$a,$b],'equipment_change')===null,'Overlay expanded item permissions');$b['status']='removed';controlAssert($get('8',[$a,$b])!==null,'Removing top did not reveal lower');$a['status']='removed';controlAssert($get('7',[$a,$b])!==null,'Removal did not read base');
$base[0]['controller_uid']='9';$base[0]['assignment_version']='2';controlAssert(AF_ACS_AuthorizationService::controller($entity,$base,$session,$roles,'9',[],'ordinary',['control_effects'=>[$a,$b]])['assignment_version']==='2','Old assignment restored');
